async def self_improve(self) -> List[str]:
        """AI ning o'zini o'zi tahlil qilib, yaxshilanish takliflarini berishi"""
        try:
            prompt = "Sen aqlli Tozalash Servis yordamchisisan. Bugungi ishingni tahlil qilib, xizmat sifatini oshirish uchun 3 ta qisqa taklif ber. Faqat JSON array qaytar: [\"Taklif 1\", \"Taklif 2\", \"Taklif 3\"]"
            response = await self.model.generate_content_async(prompt)
            json_str = response.text
            match = re.search(r'\[.*\]', json_str, re.DOTALL)
            if match:
                json_str = match.group()
            return json.loads(json_str)
        except Exception as e:
            logger.error(f"Self-improve xatosi: {e}")
            return ["Mijozlarga tezroq javob berish"]
